def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    vals = [v for row in grid for v in row]
    background = max(set(vals), key=vals.count)

    # Recolor enclosed background cavities; leave all exterior background and
    # the outline itself unchanged.
    exterior = set()
    queue = deque()
    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h - 1 or c == 0 or c == w - 1) and grid[r][c] == background:
                exterior.add((r, c))
                queue.append((r, c))
    while queue:
        r, c = queue.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background
                    and (nr, nc) not in exterior):
                exterior.add((nr, nc))
                queue.append((nr, nc))

    for r in range(h):
        for c in range(w):
            if grid[r][c] == background and (r, c) not in exterior:
                out[r][c] = 4
    return out
